const std = @import("std");

pub fn main() !void {
    const text = "Hello, Zig!";
    std.debug.print("Original: {s}\n", .{text});
    std.debug.print("ROT13: ", .{});
    for (text) |ch| {
        var rotated = ch;
        if (ch >= 'a' and ch <= 'z') {
            rotated = ((ch - 'a' + 13) % 26) + 'a';
        } else if (ch >= 'A' and ch <= 'Z') {
            rotated = ((ch - 'A' + 13) % 26) + 'A';
        }
        std.debug.print("{c}", .{rotated});
    }
    std.debug.print("\n", .{});
}
